insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1c26aad2-b9a1-5c85-960e-ae4228b413b8', 'Cells of the ascending limb [1] actively transport sodium and chloride ions out into the medulla [1]; the ascending limb is impermeable to water, so the medulla becomes hypertonic [1].', 'Cells of the ascending limb [1] actively transport sodium and chloride ions out into the medulla [1]; the ascending limb is impermeable to water, so the medulla becomes hypertonic [1].', '[{"text": "Marking point 1", "any": ["ascending"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pump", "active", "sodium", "na"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["impermeable to water", "water cannot follow", "hypertonic", "high concentration"], "all": [], "marks": 1}]'::jsonb, 'Cells of the ascending limb [1] actively transport sodium and chloride ions out into the medulla [1]; the ascending limb is impermeable to water, so the medulla becomes hypertonic [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
