insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5e77b5d2-2e02-5356-9617-393151677fe0', 'short', 'Explain how ADH reduces water loss in a dehydrated person.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5e77b5d2-2e02-5356-9617-393151677fe0', 'Osmoreceptors in the hypothalamus detect concentrated blood and the pituitary releases more ADH [1]; ADH causes aquaporins to be inserted in the collecting duct membranes [1]; more water is reabsorbed by osmosis into the medulla, producing a small volume of concentrated urine [1].', 'Osmoreceptors in the hypothalamus detect concentrated blood and the pituitary releases more ADH [1]; ADH causes aquaporins to be inserted in the collecting duct membranes [1]; more water is reabsorbed by osmosis into the medulla, producing a small volume of concentrated urine [1].', '[{"text": "Marking point 1", "any": ["hypothalamus", "osmoreceptor", "pituitary"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["aquaporin"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["reabsorb", "osmosis", "concentrated urine", "less water"], "all": [], "marks": 1}]'::jsonb, 'Osmoreceptors in the hypothalamus detect concentrated blood and the pituitary releases more ADH [1]; ADH causes aquaporins to be inserted in the collecting duct membranes [1]; more water is reabsorbed by osmosis into the medulla, producing a small volume of concentrated urine [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
