insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('964d618c-5983-559e-b46e-943d8e42b50a', 'Blood in the glomerulus is under high pressure because the efferent arteriole is narrower than the afferent [1]; fluid is forced through fenestrated capillaries, the basement membrane and between podocytes [1]; small molecules such as water, glucose and urea pass through but blood cells and large proteins do not [1].', 'Blood in the glomerulus is under high pressure because the efferent arteriole is narrower than the afferent [1]; fluid is forced through fenestrated capillaries, the basement membrane and between podocytes [1]; small molecules such as water, glucose and urea pass through but blood cells and large proteins do not [1].', '[{"text": "Marking point 1", "any": ["high pressure", "pressure", "afferent"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["basement membrane", "fenestrat", "podocyte"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["small molecules", "proteins", "cells not", "glucose"], "all": [], "marks": 1}]'::jsonb, 'Blood in the glomerulus is under high pressure because the efferent arteriole is narrower than the afferent [1]; fluid is forced through fenestrated capillaries, the basement membrane and between podocytes [1]; small molecules such as water, glucose and urea pass through but blood cells and large proteins do not [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
