insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a34ff6ec-8b53-5d9f-a521-1a1b63c84deb', 'A drug first stops the woman''s own FSH and LH secretion (down-regulation) [1]; FSH injections then stimulate many follicles to develop [1]; hCG is given to mature the eggs before collection, and progesterone supports the endometrium after transfer [1].', 'A drug first stops the woman''s own FSH and LH secretion (down-regulation) [1]; FSH injections then stimulate many follicles to develop [1]; hCG is given to mature the eggs before collection, and progesterone supports the endometrium after transfer [1].', '[{"text": "Marking point 1", "any": ["down-regulat", "stop", "suspend", "pituitary"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fsh", "many follicles", "superovulation"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hcg", "lh", "mature", "progesterone"], "all": [], "marks": 1}]'::jsonb, 'A drug first stops the woman''s own FSH and LH secretion (down-regulation) [1]; FSH injections then stimulate many follicles to develop [1]; hCG is given to mature the eggs before collection, and progesterone supports the endometrium after transfer [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
