insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a4662016-82b2-54c9-af9e-399b6932dd54', 'When the first sperm fuses, cortical granules release enzymes by exocytosis [1]; these harden the zona pellucida and destroy sperm-binding sites, so no other sperm can enter [1].', 'When the first sperm fuses, cortical granules release enzymes by exocytosis [1]; these harden the zona pellucida and destroy sperm-binding sites, so no other sperm can enter [1].', '[{"text": "Marking point 1", "any": ["cortical", "granules", "enzymes"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["zona pellucida", "harden", "block", "binding sites"], "all": [], "marks": 1}]'::jsonb, 'When the first sperm fuses, cortical granules release enzymes by exocytosis [1]; these harden the zona pellucida and destroy sperm-binding sites, so no other sperm can enter [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
