insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('98d372a2-f368-5925-ad6d-9f475c10b36d', 'hCG is secreted by the embryo (blastocyst) [1]; it maintains the corpus luteum so progesterone secretion continues and the endometrium is not shed [1].', 'hCG is secreted by the embryo (blastocyst) [1]; it maintains the corpus luteum so progesterone secretion continues and the endometrium is not shed [1].', '[{"text": "Marking point 1", "any": ["embryo", "blastocyst", "secreted"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["corpus luteum", "progesterone", "maintain"], "all": [], "marks": 1}]'::jsonb, 'hCG is secreted by the embryo (blastocyst) [1]; it maintains the corpus luteum so progesterone secretion continues and the endometrium is not shed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
