insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f0857a64-ef55-5119-8d8d-46478121ce5d', 'Brightly coloured, scented petals attract insects [1]; nectar rewards them, and sticky pollen on anthers positioned where the insect brushes past is carried to the stigma of the next flower [1].', 'Brightly coloured, scented petals attract insects [1]; nectar rewards them, and sticky pollen on anthers positioned where the insect brushes past is carried to the stigma of the next flower [1].', '[{"text": "Marking point 1", "any": ["petal", "colour", "scent", "large"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["nectar", "sticky pollen", "anthers inside", "stigma inside", "landing"], "all": [], "marks": 1}]'::jsonb, 'Brightly coloured, scented petals attract insects [1]; nectar rewards them, and sticky pollen on anthers positioned where the insect brushes past is carried to the stigma of the next flower [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
